export type ContentUnavailableResponse = {
    /**
     * Always false — present only when your own content could not be analyzed
     */
    available: boolean;
    /**
     * Why your own content is unmeasured this run. 'content_fetch_failed' = your sitemap couldn't be read; 'content_url_not_configured' = no sitemap is set up for your own domain.
     */
    reason: 'content_fetch_failed' | 'content_url_not_configured';
};

export type ContentSummaryCustomerResponse = {
    /**
     * Your domain. Unlike every other field here it is not nulled when nothing was measured, because it stays a known fact — it comes from your project's own configuration, not from the sitemap check. The one exception is a project with no own-domain entry on file at all, where there is no domain to report and this carries the literal placeholder `unknown`. That string is a marker, never a domain: don't render it, resolve it, or describe it as a site.
     */
    domain: string;
    /**
     * Total URLs discovered across all your sitemaps, or null when your own sitemap couldn't be analyzed this run. A `0` is a MEASURED finding — a sitemap we read that lists nothing — so never read a null as 0.
     */
    totalUrls: number | null;
    /**
     * Strategic URLs — the sum over the 9 strategic categories ONLY (Blog Posts, Documentation, Free Tools, Landing Pages, Case Studies, Comparison Pages, Integrations, Changelog, Webinars). Legal, Programmatic Pages, Other are counted in `categorizedCounts` and excluded here, so `totalUrls - strategicUrls` is NOT "legal plus junk": on a vendor that generates templated pages at scale, most of that difference is Programmatic Pages — a real content operation — and attributing it to noise understates them badly. Read `categorizedCounts.programmatic` before drawing any conclusion from the difference. Null when your own sitemap couldn't be analyzed this run. A `0` is a measured finding and the honest floor of the content comparison; a null means we never read the sitemap.
     */
    strategicUrls: number | null;
    /**
     * URL counts per content category, or null when your own sitemap couldn't be analyzed this run. Nulled as a whole rather than returned all-zero, because an all-zero map reads as "measured, and every category is empty" — a much stronger claim than "we couldn't look". The keys are the 12 categories we classify into: blog, docs, tools, landing, caseStudies, comparison, integrations, changelog, webinars, legal, programmatic, other. A category absent from the map has zero URLs; a category present with 0 was measured as empty. Note this map is WIDER than the set the gap analysis evaluates: Legal, Programmatic Pages, Other are counted here but never assessed for gaps, advantages or on-track status, so a category with a count here and no entry in `criticalGaps` / `advantages` / `onTrack` may simply never have been a candidate. `strategicUrls` is the sum over the 9 evaluated ones, not over this whole map.
     */
    categorizedCounts: {
        [key: string]: number;
    } | null;
    /**
     * Present ONLY when your own sitemap couldn't be analyzed this run (fetch failed, or no sitemap configured) — see `reason`. When present, every metric in this object is null, `strategicUrlGap` is null, and all four gap lists (`criticalGaps`, `significantGaps`, `advantages`, `onTrack`) and their four count siblings are null. Nothing here is a measured fact; the nulls say so on their own, and this field records why. Only `domain` remains populated — and where no domain was on file it holds the literal placeholder `unknown` rather than being omitted, so treat that exact string as 'no domain', not as a site name. This flag is a sufficient reason for those eight nulls but NOT a necessary one: they are also null when your own sitemap read fine and no competitor returned usable data (`comparableCompetitors` is 0), with this flag absent — so never conclude from a null gap list alone that YOUR check failed. Note too the difference between a null list and an empty one: `[]` means we compared and found none, which is a real finding.
     */
    contentAnalysisAvailable?: ContentUnavailableResponse;
};

